mapper.select:
SELECT id, snapshot_id, qualified_name, simple_name, package_name, kind, source_type, jar_id, doc, is_valid, created_at, updated_at
FROM yglue_project_snapshot_class
WHERE snapshot_id = #{snapshotId}
  AND qualified_name = #{qualifiedName}
LIMIT 1

SELECT id, class_id, name, type, is_static, is_valid, created_at, updated_at
FROM yglue_project_snapshot_class_field
WHERE class_id = #{classId}
ORDER BY name
LIMIT #{limit} OFFSET #{offset}

SELECT id, class_id, name, return_type, is_static, parameters_json, method_signature_hash, is_valid, created_at, updated_at
FROM yglue_project_snapshot_class_method
WHERE class_id = #{classId}
ORDER BY name
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE yglue_project_snapshot_class
SET is_valid = 0, updated_at = CURRENT_TIMESTAMP
WHERE project_id = #{projectId}

UPDATE yglue_project_dependency
SET is_valid = 0, updated_at = CURRENT_TIMESTAMP
WHERE project_id = #{projectId}

mapper.select:
SELECT id, project_id, qualified_name, simple_name, package_name, kind, source_type, jar_id, doc, is_valid, created_at, updated_at
FROM yglue_project_snapshot_class
WHERE project_id = #{projectId}
  AND qualified_name = #{qualifiedName}
  AND is_valid = 1
LIMIT 1

mapper.update:
UPDATE yglue_project_class_agg
SET is_valid = 0, updated_at = CURRENT_TIMESTAMP
WHERE project_id = #{projectId}
